fn border_cascade_order(rule_order: usize, declaration_order: usize, inline: bool) -> usize {
    if inline {
        declaration_order
    } else {
        rule_order
            .saturating_mul(CASCADE_DECLARATION_ORDER_STRIDE)
            .saturating_add(declaration_order)
    }
}

