#[cfg(test)]
fn parse_border(value: &str) -> Option<NativeBorderSide> {
    let mut parts = value.split_ascii_whitespace();
    let width = parse_dimension(parts.next()?)?;
    let style = parse_border_style(parts.next()?)?;
    let color = parts.collect::<Vec<_>>().join(" ");
    Some(NativeBorderSide {
        width,
        style,
        color: parse_color(&color)?,
    })
}

fn parse_complete_border(value: &str) -> Option<NativeBorderDeclaration> {
    let mut parts = value.split_ascii_whitespace();
    let width = parse_dimension(parts.next()?)?;
    let style = parts.next()?;
    let color = parts.collect::<Vec<_>>().join(" ");
    let color = parse_border_color_value(&color)?;
    match (parse_border_style_value(style)?, color) {
        (NativeBorderStyleValue::Paint(style), NativeBorderColorValue::Color(color)) => {
            Some(NativeBorderDeclaration::Complete(NativeBorderSide {
                width,
                style,
                color,
            }))
        }
        (NativeBorderStyleValue::Paint(style), NativeBorderColorValue::CurrentColor) => {
            Some(NativeBorderDeclaration::CompleteCurrentColor { width, style })
        }
        (NativeBorderStyleValue::None, NativeBorderColorValue::Color(color)) => {
            Some(NativeBorderDeclaration::CompleteNone { width, color })
        }
        (NativeBorderStyleValue::None, NativeBorderColorValue::CurrentColor) => {
            Some(NativeBorderDeclaration::CompleteNoneCurrentColor { width })
        }
        (NativeBorderStyleValue::Hidden, NativeBorderColorValue::Color(color)) => {
            Some(NativeBorderDeclaration::CompleteHidden { width, color })
        }
        (NativeBorderStyleValue::Hidden, NativeBorderColorValue::CurrentColor) => {
            Some(NativeBorderDeclaration::CompleteHiddenCurrentColor { width })
        }
        _ => None,
    }
}

fn parse_border_declaration(
    value: &str,
) -> Option<LocalCascadeDeclaration<NativeBorderDeclaration>> {
    let value = value.trim();
    if value.eq_ignore_ascii_case("revert-layer") {
        return Some(LocalCascadeDeclaration::RevertLayer);
    }
    if value.eq_ignore_ascii_case("none") {
        return Some(LocalCascadeDeclaration::Value(
            NativeBorderDeclaration::None,
        ));
    }
    if value.eq_ignore_ascii_case("hidden") {
        return Some(LocalCascadeDeclaration::Value(
            NativeBorderDeclaration::Hidden,
        ));
    }
    for (keyword, declaration) in [
        ("inherit", NativeBorderDeclaration::Inherit),
        ("unset", NativeBorderDeclaration::Unset),
        ("initial", NativeBorderDeclaration::Initial),
        ("revert", NativeBorderDeclaration::Revert),
    ] {
        if value.eq_ignore_ascii_case(keyword) {
            return Some(LocalCascadeDeclaration::Value(declaration));
        }
    }
    parse_complete_border(value).map(LocalCascadeDeclaration::Value)
}

fn parse_border_width_declaration(
    value: &str,
) -> Option<[LocalCascadeDeclaration<NativeBorderWidthValue>; 4]> {
    if value.trim().eq_ignore_ascii_case("revert-layer") {
        return Some([LocalCascadeDeclaration::RevertLayer; 4]);
    }
    let values = split_css_value_tokens(value)?
        .into_iter()
        .map(parse_border_width_value)
        .collect::<Option<Vec<_>>>()?;
    if values.len() != 1 && values.iter().any(|value| value.is_css_wide()) {
        return None;
    }
    expand_box_edges(&values).map(|values| values.map(LocalCascadeDeclaration::Value))
}

fn parse_border_width_side_declaration(
    value: &str,
) -> Option<LocalCascadeDeclaration<NativeBorderWidthValue>> {
    parse_local_cascade_declaration(value, parse_border_width_value)
}

fn parse_border_width_value(value: &str) -> Option<NativeBorderWidthValue> {
    let value = value.trim();
    if value.eq_ignore_ascii_case("inherit") {
        Some(NativeBorderWidthValue::Inherit)
    } else if value.eq_ignore_ascii_case("unset") {
        Some(NativeBorderWidthValue::Unset)
    } else if value.eq_ignore_ascii_case("initial") {
        Some(NativeBorderWidthValue::Initial)
    } else if value.eq_ignore_ascii_case("revert") {
        Some(NativeBorderWidthValue::Revert)
    } else {
        parse_dimension(value).map(NativeBorderWidthValue::Width)
    }
}

fn parse_border_style_declaration(
    value: &str,
) -> Option<[LocalCascadeDeclaration<NativeBorderStyleValue>; 4]> {
    if value.trim().eq_ignore_ascii_case("revert-layer") {
        return Some([LocalCascadeDeclaration::RevertLayer; 4]);
    }
    let values = split_css_value_tokens(value)?
        .into_iter()
        .map(parse_border_style_value)
        .collect::<Option<Vec<_>>>()?;
    if values.len() != 1 && values.iter().any(|value| value.is_css_wide()) {
        return None;
    }
    expand_box_edges(&values).map(|values| values.map(LocalCascadeDeclaration::Value))
}

fn parse_border_style_side_declaration(
    value: &str,
) -> Option<LocalCascadeDeclaration<NativeBorderStyleValue>> {
    parse_local_cascade_declaration(value, parse_border_style_value)
}

fn parse_border_color(value: &str) -> Option<[NativeBorderColorValue; 4]> {
    let values = split_css_value_tokens(value)?
        .into_iter()
        .map(parse_border_color_value)
        .collect::<Option<Vec<_>>>()?;
    if values.len() != 1 && values.iter().any(|value| value.is_css_wide()) {
        return None;
    }
    match values.as_slice() {
        [all] => Some([*all; 4]),
        [top, right] => Some([*top, *right, *top, *right]),
        [top, horizontal, bottom] => Some([*top, *horizontal, *bottom, *horizontal]),
        [top, right, bottom, left] => Some([*top, *right, *bottom, *left]),
        _ => None,
    }
}

fn parse_border_color_declaration(
    value: &str,
) -> Option<[LocalCascadeDeclaration<NativeBorderColorValue>; 4]> {
    if value.trim().eq_ignore_ascii_case("revert-layer") {
        return Some([LocalCascadeDeclaration::RevertLayer; 4]);
    }
    parse_border_color(value).map(|values| values.map(LocalCascadeDeclaration::Value))
}

fn parse_border_color_side_declaration(
    value: &str,
) -> Option<LocalCascadeDeclaration<NativeBorderColorValue>> {
    parse_local_cascade_declaration(value, parse_border_color_value)
}

fn parse_logical_component_pair<T: Copy>(
    value: &str,
    parse_value: impl Fn(&str) -> Option<T>,
    is_css_wide: impl Fn(T) -> bool,
) -> Option<[LocalCascadeDeclaration<T>; 2]> {
    if value.trim().eq_ignore_ascii_case("revert-layer") {
        return Some([LocalCascadeDeclaration::RevertLayer; 2]);
    }
    let values = split_css_value_tokens(value)?
        .into_iter()
        .map(parse_value)
        .collect::<Option<Vec<_>>>()?;
    if values.len() != 1 && values.iter().copied().any(is_css_wide) {
        return None;
    }
    match values.as_slice() {
        [value] => Some([LocalCascadeDeclaration::Value(*value); 2]),
        [start, end] => Some([
            LocalCascadeDeclaration::Value(*start),
            LocalCascadeDeclaration::Value(*end),
        ]),
        _ => None,
    }
}

fn parse_logical_border_width_pair(
    value: &str,
) -> Option<[LocalCascadeDeclaration<NativeBorderWidthValue>; 2]> {
    parse_logical_component_pair(
        value,
        parse_border_width_value,
        NativeBorderWidthValue::is_css_wide,
    )
}

fn parse_logical_border_style_pair(
    value: &str,
) -> Option<[LocalCascadeDeclaration<NativeBorderStyleValue>; 2]> {
    parse_logical_component_pair(
        value,
        parse_border_style_value,
        NativeBorderStyleValue::is_css_wide,
    )
}

fn parse_logical_border_color_pair(
    value: &str,
) -> Option<[LocalCascadeDeclaration<NativeBorderColorValue>; 2]> {
    parse_logical_component_pair(
        value,
        parse_border_color_value,
        NativeBorderColorValue::is_css_wide,
    )
}

fn parse_border_color_value(value: &str) -> Option<NativeBorderColorValue> {
    let value = value.trim();
    if value.eq_ignore_ascii_case("currentColor") {
        Some(NativeBorderColorValue::CurrentColor)
    } else if value.eq_ignore_ascii_case("inherit") {
        Some(NativeBorderColorValue::Inherit)
    } else if value.eq_ignore_ascii_case("unset") {
        Some(NativeBorderColorValue::Unset)
    } else if value.eq_ignore_ascii_case("initial") {
        Some(NativeBorderColorValue::Initial)
    } else if value.eq_ignore_ascii_case("revert") {
        Some(NativeBorderColorValue::Revert)
    } else {
        parse_color(value).map(NativeBorderColorValue::Color)
    }
}

impl NativeBorderColorValue {
    const fn is_css_wide(self) -> bool {
        matches!(
            self,
            Self::Inherit | Self::Unset | Self::Initial | Self::Revert
        )
    }
}

fn parse_background_color_value(value: &str) -> Option<NativeBackgroundColorValue> {
    let value = value.trim();
    if value.eq_ignore_ascii_case("currentColor") {
        Some(NativeBackgroundColorValue::CurrentColor)
    } else if value.eq_ignore_ascii_case("inherit") {
        Some(NativeBackgroundColorValue::Inherit)
    } else if value.eq_ignore_ascii_case("unset") {
        Some(NativeBackgroundColorValue::Unset)
    } else if value.eq_ignore_ascii_case("initial") {
        Some(NativeBackgroundColorValue::Initial)
    } else if value.eq_ignore_ascii_case("revert") {
        Some(NativeBackgroundColorValue::Revert)
    } else {
        parse_color(value).map(NativeBackgroundColorValue::Color)
    }
}

fn parse_background_color_declaration(
    value: &str,
) -> Option<LocalCascadeDeclaration<NativeBackgroundColorValue>> {
    parse_local_cascade_declaration(value, parse_background_color_value)
}

fn background_image_source_id(source: &str) -> u32 {
    let mut hash = 2_166_136_261u32;
    for byte in source.bytes() {
        hash ^= u32::from(byte);
        hash = hash.wrapping_mul(16_777_619);
    }
    if hash == 0 { 1 } else { hash }
}

fn parse_background_image_url(value: &str) -> Option<&str> {
    let value = value.trim();
    let open = value.find('(')?;
    if !value[..open].trim().eq_ignore_ascii_case("url") || !value.ends_with(')') {
        return None;
    }
    let inner = value[open + 1..value.len().saturating_sub(1)].trim();
    if inner.len() > 2 {
        let bytes = inner.as_bytes();
        if matches!(bytes.first(), Some(b'"' | b'\'')) {
            if bytes.last() != bytes.first() {
                return None;
            }
            let inner = &inner[1..inner.len().saturating_sub(1)];
            if inner.is_empty()
                || inner.len() > 1024
                || inner.bytes().any(|byte| byte.is_ascii_control())
            {
                return None;
            }
            return Some(inner);
        }
    }
    if inner.is_empty()
        || inner.len() > 1024
        || inner
            .bytes()
            .any(|byte| byte.is_ascii_whitespace() || byte.is_ascii_control())
    {
        return None;
    }
    Some(inner)
}

fn parse_background_image_value(value: &str) -> Option<NativeBackgroundImageValue> {
    let value = value.trim();
    if value.eq_ignore_ascii_case("none") {
        return Some(NativeBackgroundImageValue::None);
    }
    if value.eq_ignore_ascii_case("inherit") {
        return Some(NativeBackgroundImageValue::Inherit);
    }
    if value.eq_ignore_ascii_case("unset") {
        return Some(NativeBackgroundImageValue::Unset);
    }
    if value.eq_ignore_ascii_case("initial") {
        return Some(NativeBackgroundImageValue::Initial);
    }
    if value.eq_ignore_ascii_case("revert") {
        return Some(NativeBackgroundImageValue::Revert);
    }
    parse_background_image_url(value)
        .map(background_image_source_id)
        .map(NativeBackgroundImageValue::Url)
}

fn parse_background_image_declaration(
    value: &str,
) -> Option<LocalCascadeDeclaration<NativeBackgroundImageValue>> {
    parse_local_cascade_declaration(value, parse_background_image_value)
}

fn parse_background_repeat(value: &str) -> Option<NativeBackgroundRepeat> {
    let tokens = value
        .split_ascii_whitespace()
        .map(|token| token.to_ascii_lowercase())
        .collect::<Vec<_>>();
    match tokens.as_slice() {
        [repeat] => match repeat.as_str() {
            "repeat" => Some(NativeBackgroundRepeat::Repeat),
            "repeat-x" => Some(NativeBackgroundRepeat::RepeatX),
            "repeat-y" => Some(NativeBackgroundRepeat::RepeatY),
            "no-repeat" => Some(NativeBackgroundRepeat::NoRepeat),
            _ => None,
        },
        [horizontal, vertical] => match (horizontal.as_str(), vertical.as_str()) {
            ("repeat", "repeat") => Some(NativeBackgroundRepeat::Repeat),
            ("repeat", "no-repeat") => Some(NativeBackgroundRepeat::RepeatX),
            ("no-repeat", "repeat") => Some(NativeBackgroundRepeat::RepeatY),
            ("no-repeat", "no-repeat") => Some(NativeBackgroundRepeat::NoRepeat),
            _ => None,
        },
        _ => None,
    }
}

fn parse_background_repeat_declaration(
    value: &str,
) -> Option<LocalCascadeDeclaration<NativeBackgroundRepeat>> {
    if is_inherit_keyword(value) {
        return Some(LocalCascadeDeclaration::Inherit);
    }
    parse_local_reset_cascade_declaration(value, parse_background_repeat)
}

fn parse_background_percentage(value: &str) -> Option<i32> {
    let value = value.trim();
    let value = value.strip_suffix('%')?.trim();
    let (negative, value) = value
        .strip_prefix('-')
        .map_or((false, value), |value| (true, value));
    let milli = i64::from(parse_decimal_milli(value)?);
    let scaled = (milli + 50) / 100;
    let scaled = if negative { -scaled } else { scaled };
    (scaled.abs() <= i64::from(MAX_NATIVE_BACKGROUND_PERCENT))
        .then(|| i32::try_from(scaled).ok())
        .flatten()
}

fn parse_background_pixel(value: &str) -> Option<i32> {
    let value = value.trim().to_ascii_lowercase();
    let (negative, value) = value
        .strip_prefix('-')
        .map_or((false, value.as_str()), |value| (true, value));
    let value = if value == "0" {
        value
    } else {
        value.strip_suffix("px")?.trim()
    };
    let milli = i64::from(parse_decimal_milli(value)?);
    let pixels = (milli + 500) / 1_000;
    let pixels = if negative { -pixels } else { pixels };
    (pixels.abs() <= i64::from(MAX_NATIVE_VIEWPORT_DIMENSION))
        .then(|| i32::try_from(pixels).ok())
        .flatten()
}

fn parse_background_position_axis_component(
    value: &str,
    horizontal: bool,
) -> Option<NativeBackgroundPositionComponent> {
    match value.trim().to_ascii_lowercase().as_str() {
        "left" if horizontal => Some(NativeBackgroundPositionComponent::Percentage(0)),
        "right" if horizontal => Some(NativeBackgroundPositionComponent::Percentage(
            NATIVE_BACKGROUND_PERCENT_SCALE,
        )),
        "top" if !horizontal => Some(NativeBackgroundPositionComponent::Percentage(0)),
        "bottom" if !horizontal => Some(NativeBackgroundPositionComponent::Percentage(
            NATIVE_BACKGROUND_PERCENT_SCALE,
        )),
        "center" => Some(NativeBackgroundPositionComponent::Percentage(
            NATIVE_BACKGROUND_PERCENT_SCALE / 2,
        )),
        value if value.ends_with('%') => {
            parse_background_percentage(value).map(NativeBackgroundPositionComponent::Percentage)
        }
        value => parse_background_pixel(value).map(NativeBackgroundPositionComponent::Length),
    }
}

fn parse_background_position(value: &str) -> Option<NativeBackgroundPosition> {
    let tokens = split_css_value_tokens(value)?;
    match tokens.as_slice() {
        [value] => {
            if let Some(x) = parse_background_position_axis_component(value, true) {
                Some(NativeBackgroundPosition {
                    x,
                    y: NativeBackgroundPositionComponent::Percentage(
                        NATIVE_BACKGROUND_PERCENT_SCALE / 2,
                    ),
                })
            } else {
                parse_background_position_axis_component(value, false).map(|y| {
                    NativeBackgroundPosition {
                        x: NativeBackgroundPositionComponent::Percentage(
                            NATIVE_BACKGROUND_PERCENT_SCALE / 2,
                        ),
                        y,
                    }
                })
            }
        }
        [first, second] => {
            if let (Some(x), Some(y)) = (
                parse_background_position_axis_component(first, true),
                parse_background_position_axis_component(second, false),
            ) {
                Some(NativeBackgroundPosition { x, y })
            } else if let (Some(y), Some(x)) = (
                parse_background_position_axis_component(first, false),
                parse_background_position_axis_component(second, true),
            ) {
                Some(NativeBackgroundPosition { x, y })
            } else {
                None
            }
        }
        _ => None,
    }
}

fn parse_background_position_declaration(
    value: &str,
) -> Option<LocalCascadeDeclaration<NativeBackgroundPosition>> {
    if is_inherit_keyword(value) {
        return Some(LocalCascadeDeclaration::Inherit);
    }
    parse_local_reset_cascade_declaration(value, parse_background_position)
}

fn parse_background_size_component(value: &str) -> Option<NativeBackgroundSizeComponent> {
    let value = value.trim();
    if value.eq_ignore_ascii_case("auto") {
        return Some(NativeBackgroundSizeComponent::Auto);
    }
    if value.ends_with('%') {
        return u32::try_from(parse_background_percentage(value).filter(|value| *value >= 0)?)
            .ok()
            .map(NativeBackgroundSizeComponent::Percentage);
    }
    u32::try_from(parse_background_pixel(value).filter(|value| *value >= 0)?)
        .ok()
        .map(NativeBackgroundSizeComponent::Length)
}

fn parse_background_size(value: &str) -> Option<NativeBackgroundSize> {
    let value = value.trim();
    if value.eq_ignore_ascii_case("cover") {
        return Some(NativeBackgroundSize::Cover);
    }
    if value.eq_ignore_ascii_case("contain") {
        return Some(NativeBackgroundSize::Contain);
    }
    let tokens = split_css_value_tokens(value)?;
    match tokens.as_slice() {
        [width] => Some(NativeBackgroundSize::Explicit {
            width: parse_background_size_component(width)?,
            height: NativeBackgroundSizeComponent::Auto,
        }),
        [width, height] => Some(NativeBackgroundSize::Explicit {
            width: parse_background_size_component(width)?,
            height: parse_background_size_component(height)?,
        }),
        _ => None,
    }
}

fn parse_background_size_declaration(
    value: &str,
) -> Option<LocalCascadeDeclaration<NativeBackgroundSize>> {
    if is_inherit_keyword(value) {
        return Some(LocalCascadeDeclaration::Inherit);
    }
    parse_local_reset_cascade_declaration(value, parse_background_size)
}

fn split_background_size_separator(value: &str) -> Option<(&str, Option<&str>)> {
    let mut parentheses = 0usize;
    let mut quote = None;
    let mut escaped = false;
    let mut separator = None;
    for (index, byte) in value.bytes().enumerate() {
        if let Some(delimiter) = quote {
            if escaped {
                escaped = false;
            } else if byte == b'\\' {
                escaped = true;
            } else if byte == delimiter {
                quote = None;
            }
            continue;
        }
        match byte {
            b'\'' | b'"' => quote = Some(byte),
            b'(' => parentheses = parentheses.checked_add(1)?,
            b')' => parentheses = parentheses.checked_sub(1)?,
            b'/' if parentheses == 0 && separator.replace(index).is_some() => {
                return None;
            }
            _ => {}
        }
    }
    if parentheses != 0 || quote.is_some() {
        return None;
    }
    match separator {
        Some(index) => {
            let before = value[..index].trim();
            let after = value[index.saturating_add(1)..].trim();
            (!before.is_empty() && !after.is_empty()).then_some((before, Some(after)))
        }
        None => Some((value.trim(), None)),
    }
}

fn parse_background_shorthand(value: &str) -> Option<NativeBackgroundShorthand> {
    let (before_size, after_size) = split_background_size_separator(value)?;
    let tokens = split_css_value_tokens(before_size)?;
    let mut color = None;
    let mut image = None;
    let mut repeat = None;
    let mut position_tokens = Vec::new();
    for token in tokens {
        if image.is_none()
            && let Some(parsed) = parse_background_image_value(token)
            && matches!(
                parsed,
                NativeBackgroundImageValue::Url(_) | NativeBackgroundImageValue::None
            )
        {
            image = Some(parsed);
            continue;
        }
        if repeat.is_none()
            && let Some(parsed) = parse_background_repeat(token)
        {
            repeat = Some(parsed);
            continue;
        }
        if color.is_none()
            && let Some(parsed) = parse_background_color_value(token)
            && matches!(
                parsed,
                NativeBackgroundColorValue::Color(_) | NativeBackgroundColorValue::CurrentColor
            )
        {
            color = Some(parsed);
            continue;
        }
        position_tokens.push(token);
    }

    let position = if position_tokens.is_empty() {
        NativeBackgroundPosition::default()
    } else {
        parse_background_position(&position_tokens.join(" "))?
    };
    let mut size_tokens = match after_size {
        Some(value) => split_css_value_tokens(value)?,
        None => Vec::new(),
    };
    if repeat.is_none()
        && let Some(last) = size_tokens.last().copied()
        && let Some(parsed) = parse_background_repeat(last)
    {
        repeat = Some(parsed);
        size_tokens.pop();
    }
    let size = if size_tokens.is_empty() {
        NativeBackgroundSize::default()
    } else {
        parse_background_size(&size_tokens.join(" "))?
    };
    Some(NativeBackgroundShorthand {
        color: color.unwrap_or(NativeBackgroundColorValue::Color(NativeColor {
            red: 0,
            green: 0,
            blue: 0,
            alpha: 0,
        })),
        image: image.unwrap_or(NativeBackgroundImageValue::None),
        repeat: repeat.unwrap_or_default(),
        position,
        size,
    })
}

fn parse_background_shorthand_declaration(
    value: &str,
) -> Option<NativeBackgroundShorthandDeclaration> {
    let value = value.trim();
    if value.eq_ignore_ascii_case("revert-layer") {
        return Some(NativeBackgroundShorthandDeclaration::RevertLayer);
    }
    if value.eq_ignore_ascii_case("inherit") {
        return Some(NativeBackgroundShorthandDeclaration::Inherit);
    }
    if is_local_reset_keyword(value) {
        return Some(NativeBackgroundShorthandDeclaration::Reset);
    }
    parse_background_shorthand(value).map(NativeBackgroundShorthandDeclaration::Value)
}

pub(crate) fn collect_background_image_sources(
    source: &str,
    background_image_sources: &mut BTreeMap<u32, String>,
) {
    for (_, declaration) in split_css_declarations(source) {
        let Some((property, value)) = declaration.split_once(':') else {
            continue;
        };
        let (value, _) = strip_important_suffix(value);
        if property.trim().eq_ignore_ascii_case("background-image") {
            if let Some(source) = parse_background_image_url(value) {
                register_background_image_source(source, background_image_sources);
            }
        } else if property.trim().eq_ignore_ascii_case("background")
            && parse_background_shorthand(value).is_some()
            && let Some(tokens) = split_css_value_tokens(value)
        {
            for token in tokens {
                if let Some(source) = parse_background_image_url(token) {
                    register_background_image_source(source, background_image_sources);
                }
            }
        }
    }
}

/// Resolve relative CSS `url(...)` tokens against the loaded stylesheet URL.
/// The CSS parser stores background-image identities as source strings, so
/// canonicalizing before parsing gives each stylesheet its own URL base
/// without changing the declaration/cascade model. File and HTTP(S) owners
/// are kept on their corresponding resource paths; blob, data, fixture, and
/// unsupported owners are returned byte-for-byte unchanged.
pub(crate) fn absolutize_stylesheet_urls(
    source: &str,
    document_url: &str,
    stylesheet_href: &str,
) -> String {
    let Some(base_url) = stylesheet_base_url(document_url, stylesheet_href) else {
        return source.to_owned();
    };
    let bytes = source.as_bytes();
    let mut rewritten = String::with_capacity(source.len());
    let mut cursor = 0usize;
    while cursor < bytes.len() {
        if bytes[cursor] == b'/' && bytes.get(cursor + 1) == Some(&b'*') {
            let end = source[cursor + 2..]
                .find("*/")
                .map(|offset| cursor + 2 + offset + 2)
                .unwrap_or(bytes.len());
            rewritten.push_str(&source[cursor..end]);
            cursor = end;
            continue;
        }
        if matches!(bytes[cursor], b'\'' | b'"') {
            let quote = bytes[cursor];
            let mut end = cursor + 1;
            let mut escaped = false;
            while end < bytes.len() {
                let byte = bytes[end];
                end += 1;
                if escaped {
                    escaped = false;
                } else if byte == b'\\' {
                    escaped = true;
                } else if byte == quote {
                    break;
                }
            }
            rewritten.push_str(&source[cursor..end]);
            cursor = end;
            continue;
        }
        let Some(open) = css_url_function_open(bytes, cursor) else {
            let character = source[cursor..]
                .chars()
                .next()
                .expect("CSS cursor must point at a character");
            let end = cursor + character.len_utf8();
            rewritten.push_str(&source[cursor..end]);
            cursor = end;
            continue;
        };
        let Some(close) = css_url_function_close(bytes, open + 1) else {
            let character = source[cursor..]
                .chars()
                .next()
                .expect("CSS cursor must point at a character");
            let end = cursor + character.len_utf8();
            rewritten.push_str(&source[cursor..end]);
            cursor = end;
            continue;
        };
        let mut value_start = open + 1;
        while value_start < close && bytes[value_start].is_ascii_whitespace() {
            value_start += 1;
        }
        let mut value_end = close;
        while value_end > value_start && bytes[value_end - 1].is_ascii_whitespace() {
            value_end -= 1;
        }
        rewritten.push_str(&source[cursor..value_start]);
        if value_start < value_end {
            let token = &source[value_start..value_end];
            if let Some(resolved) = resolve_css_url_token(token, &base_url) {
                rewritten.push_str(&resolved);
            } else {
                rewritten.push_str(token);
            }
        }
        rewritten.push_str(&source[value_end..=close]);
        cursor = close + 1;
    }
    rewritten
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct NativeCssImport {
    pub(crate) start: usize,
    pub(crate) end: usize,
    pub(crate) specifier: String,
    pub(crate) layer: Option<String>,
    pub(crate) supports: Option<String>,
    pub(crate) media: Option<String>,
}

/// Return literal CSS `@import` statements with their bounded conditional
/// preludes. The caller owns URL resolution and graph limits; this pass only
/// discovers quoted or `url(...)` targets outside comments/strings. A
/// malformed import is rejected instead of being silently left for the
/// ordinary CSS parser, so a rooted stylesheet cannot partially apply around
/// a failed dependency.
pub(crate) fn static_css_imports(source: &str) -> Result<Vec<NativeCssImport>, &'static str> {
    let bytes = source.as_bytes();
    let mut imports = Vec::new();
    let mut cursor = 0usize;
    while cursor < bytes.len() {
        if bytes[cursor] == b'/' && bytes.get(cursor + 1) == Some(&b'*') {
            cursor = css_comment_end(bytes, cursor);
            continue;
        }
        if matches!(bytes[cursor], b'\'' | b'"') {
            cursor = css_quoted_end(bytes, cursor);
            continue;
        }
        const IMPORT: &[u8] = b"@import";
        let keyword_end = cursor.saturating_add(IMPORT.len());
        if keyword_end <= bytes.len()
            && bytes[cursor..keyword_end].eq_ignore_ascii_case(IMPORT)
            && (cursor == 0 || !is_css_identifier_byte(bytes[cursor - 1]))
            && (keyword_end == bytes.len() || !is_css_identifier_byte(bytes[keyword_end]))
            && let Some(statement_end) = css_statement_end(bytes, keyword_end)
        {
            let (specifier, layer, supports, media) =
                css_import_parts(&source[keyword_end..statement_end], cursor)
                    .ok_or("CSS @import statement has no supported literal URL")?;
            imports.push(NativeCssImport {
                start: cursor,
                end: statement_end + 1,
                specifier,
                layer,
                supports,
                media,
            });
            cursor = statement_end + 1;
            continue;
        }
        if keyword_end <= bytes.len()
            && bytes[cursor..keyword_end].eq_ignore_ascii_case(IMPORT)
            && (cursor == 0 || !is_css_identifier_byte(bytes[cursor - 1]))
            && (keyword_end == bytes.len() || !is_css_identifier_byte(bytes[keyword_end]))
        {
            return Err("CSS @import statement is missing a terminating semicolon");
        }
        cursor += 1;
    }
    Ok(imports)
}

fn css_comment_end(bytes: &[u8], start: usize) -> usize {
    bytes[start + 2..]
        .windows(2)
        .position(|window| window == b"*/")
        .map(|offset| start + 2 + offset + 2)
        .unwrap_or(bytes.len())
}

fn css_quoted_end(bytes: &[u8], start: usize) -> usize {
    let quote = bytes[start];
    let mut escaped = false;
    let mut cursor = start + 1;
    while cursor < bytes.len() {
        let byte = bytes[cursor];
        cursor += 1;
        if escaped {
            escaped = false;
        } else if byte == b'\\' {
            escaped = true;
        } else if byte == quote {
            break;
        }
    }
    cursor
}

fn css_statement_end(bytes: &[u8], start: usize) -> Option<usize> {
    let mut parentheses = 0usize;
    let mut cursor = start;
    while cursor < bytes.len() {
        if bytes[cursor] == b'/' && bytes.get(cursor + 1) == Some(&b'*') {
            cursor = css_comment_end(bytes, cursor);
            continue;
        }
        if matches!(bytes[cursor], b'\'' | b'"') {
            cursor = css_quoted_end(bytes, cursor);
            continue;
        }
        match bytes[cursor] {
            b'(' => parentheses = parentheses.saturating_add(1),
            b')' => parentheses = parentheses.saturating_sub(1),
            b';' if parentheses == 0 => return Some(cursor),
            _ => {}
        }
        cursor += 1;
    }
    None
}

fn css_import_parts(
    statement: &str,
    import_start: usize,
) -> Option<(String, Option<String>, Option<String>, Option<String>)> {
    let bytes = statement.as_bytes();
    let start = css_skip_whitespace_and_comments(bytes, 0)?;
    if start >= bytes.len() {
        return None;
    }
    let (specifier, tail_start) = if matches!(bytes[start], b'\'' | b'"') {
        let quote = bytes[start];
        let end = css_quoted_end(bytes, start);
        if end <= start + 1 || bytes.get(end.saturating_sub(1)) != Some(&quote) {
            return None;
        }
        (statement[start + 1..end - 1].to_owned(), end)
    } else {
        let open = css_url_function_open(bytes, start)?;
        let close = css_url_function_close(bytes, open + 1)?;
        let mut value_start = open + 1;
        while value_start < close && bytes[value_start].is_ascii_whitespace() {
            value_start += 1;
        }
        let mut value_end = close;
        while value_end > value_start && bytes[value_end - 1].is_ascii_whitespace() {
            value_end -= 1;
        }
        if value_start == value_end {
            return None;
        }
        let token = &statement[value_start..value_end];
        let specifier = if matches!(token.as_bytes().first(), Some(b'\'' | b'"')) {
            if token.len() < 2 || token.as_bytes().last() != token.as_bytes().first() {
                return None;
            }
            token[1..token.len() - 1].to_owned()
        } else {
            token.to_owned()
        };
        (specifier, close + 1)
    };
    let mut cursor = css_skip_whitespace_and_comments(bytes, tail_start)?;
    let mut layer = None;
    if css_keyword_at(bytes, cursor, b"layer") {
        cursor = cursor.saturating_add(b"layer".len());
        let after_keyword = css_skip_whitespace_and_comments(bytes, cursor)?;
        if bytes.get(after_keyword) == Some(&b'(') {
            let close = css_parenthesized_end(bytes, after_keyword)?;
            let name_source = statement[after_keyword + 1..close].trim();
            let (name, next) = read_identifier(name_source, 0)?;
            if next != name_source.len() {
                return None;
            }
            layer = Some(name);
            cursor = close + 1;
        } else {
            layer = Some(format!("__native_import_layer_{import_start}"));
            cursor = after_keyword;
        }
    }
    cursor = css_skip_whitespace_and_comments(bytes, cursor)?;
    let mut supports = None;
    if css_keyword_at(bytes, cursor, b"supports") {
        cursor = cursor.saturating_add(b"supports".len());
        let open = css_skip_whitespace_and_comments(bytes, cursor)?;
        if bytes.get(open) != Some(&b'(') {
            return None;
        }
        let close = css_parenthesized_end(bytes, open)?;
        let condition = statement[open + 1..close].trim();
        if condition.is_empty() {
            return None;
        }
        supports = Some(condition.to_owned());
        cursor = close + 1;
    }
    cursor = css_skip_whitespace_and_comments(bytes, cursor)?;
    let media = (cursor < bytes.len()).then(|| statement[cursor..].trim().to_owned());
    Some((specifier, layer, supports, media))
}

fn css_skip_whitespace_and_comments(bytes: &[u8], mut cursor: usize) -> Option<usize> {
    loop {
        while cursor < bytes.len() && bytes[cursor].is_ascii_whitespace() {
            cursor += 1;
        }
        if bytes.get(cursor..cursor.saturating_add(2)) != Some(b"/*") {
            return Some(cursor);
        }
        let end = bytes[cursor + 2..]
            .windows(2)
            .position(|window| window == b"*/")?;
        cursor = cursor + 2 + end + 2;
    }
}

fn css_parenthesized_end(bytes: &[u8], open: usize) -> Option<usize> {
    let mut depth = 0usize;
    let mut quote = None;
    let mut escaped = false;
    let mut cursor = open;
    while cursor < bytes.len() {
        if let Some(delimiter) = quote {
            if escaped {
                escaped = false;
            } else if bytes[cursor] == b'\\' {
                escaped = true;
            } else if bytes[cursor] == delimiter {
                quote = None;
            }
            cursor += 1;
            continue;
        }
        if bytes.get(cursor..cursor.saturating_add(2)) == Some(b"/*") {
            let end = bytes[cursor + 2..]
                .windows(2)
                .position(|window| window == b"*/")?;
            cursor = cursor + 2 + end + 2;
            continue;
        }
        match bytes[cursor] {
            b'\'' | b'"' => quote = Some(bytes[cursor]),
            b'(' => depth = depth.checked_add(1)?,
            b')' => {
                depth = depth.checked_sub(1)?;
                if depth == 0 {
                    return Some(cursor);
                }
            }
            b'\\' => cursor = cursor.saturating_add(1),
            _ => {}
        }
        cursor += 1;
    }
    None
}

fn css_keyword_at(bytes: &[u8], start: usize, keyword: &[u8]) -> bool {
    let Some(end) = start.checked_add(keyword.len()) else {
        return false;
    };
    end <= bytes.len()
        && bytes[start..end].eq_ignore_ascii_case(keyword)
        && (start == 0 || !is_css_identifier_byte(bytes[start - 1]))
        && (end == bytes.len() || !is_css_identifier_byte(bytes[end]))
}

/// Return whether a parsed import's bounded media and feature conditions are
/// active for the native viewport. Unknown media features or unsupported
/// declarations remain inactive instead of granting an import capability.
pub(crate) fn css_import_matches(import: &NativeCssImport, viewport: Viewport) -> bool {
    import
        .supports
        .as_deref()
        .is_none_or(css_supports_condition_matches)
        && import
            .media
            .as_deref()
            .is_none_or(|media| css_media_list_matches(media, viewport))
}

fn css_media_list_matches(source: &str, viewport: Viewport) -> bool {
    let Some(queries) = css_top_level_segments(source, b',') else {
        return false;
    };
    queries
        .into_iter()
        .any(|query| css_media_query_matches(query.trim(), viewport))
}

fn css_media_query_matches(source: &str, viewport: Viewport) -> bool {
    let Some(words) = css_top_level_words(source) else {
        return false;
    };
    if words.is_empty() {
        return false;
    }
    let mut cursor = 0usize;
    let mut invert = false;
    if words[cursor].eq_ignore_ascii_case("not") {
        invert = true;
        cursor += 1;
    } else if words[cursor].eq_ignore_ascii_case("only") {
        cursor += 1;
    }
    if cursor >= words.len() {
        return false;
    }
    let mut matches = true;
    if !words[cursor].starts_with('(') {
        matches = matches!(
            words[cursor].to_ascii_lowercase().as_str(),
            "all" | "screen"
        );
        cursor += 1;
    }
    while cursor < words.len() {
        if !words[cursor].eq_ignore_ascii_case("and") {
            return false;
        }
        cursor += 1;
        let Some(feature) = words.get(cursor) else {
            return false;
        };
        matches &= css_media_feature_matches(feature, viewport);
        cursor += 1;
    }
    if invert { !matches } else { matches }
}

fn css_media_feature_matches(source: &str, viewport: Viewport) -> bool {
    let Some(feature) = source
        .strip_prefix('(')
        .and_then(|source| source.strip_suffix(')'))
    else {
        return false;
    };
    let Some((name, value)) = feature.split_once(':') else {
        return matches!(feature.trim().to_ascii_lowercase().as_str(), "color");
    };
    let name = name.trim().to_ascii_lowercase();
    let value = value.trim().to_ascii_lowercase();
    match name.as_str() {
        "min-width" => css_media_length(&value).is_some_and(|value| viewport.width >= value),
        "max-width" => css_media_length(&value).is_some_and(|value| viewport.width <= value),
        "min-height" => css_media_length(&value).is_some_and(|value| viewport.height >= value),
        "max-height" => css_media_length(&value).is_some_and(|value| viewport.height <= value),
        "orientation" => match value.as_str() {
            "landscape" => viewport.width >= viewport.height,
            "portrait" => viewport.width < viewport.height,
            _ => false,
        },
        "prefers-color-scheme" => value == "light",
        _ => false,
    }
}

fn css_media_length(value: &str) -> Option<u32> {
    let value = value.strip_suffix("px").map_or(value, str::trim).trim();
    value.parse().ok()
}

fn css_supports_condition_matches(source: &str) -> bool {
    fn evaluate(source: &str, depth: usize) -> bool {
        if depth > 32 {
            return false;
        }
        let source = source.trim();
        if source.is_empty() {
            return false;
        }
        if let Some(parts) = css_split_top_level_keyword(source, "or") {
            return parts.into_iter().any(|part| evaluate(part, depth + 1));
        }
        if let Some(parts) = css_split_top_level_keyword(source, "and") {
            return parts.into_iter().all(|part| evaluate(part, depth + 1));
        }
        if source
            .get(..3)
            .is_some_and(|prefix| prefix.eq_ignore_ascii_case("not"))
            && source
                .as_bytes()
                .get(3)
                .is_some_and(u8::is_ascii_whitespace)
        {
            return !evaluate(&source[4..], depth + 1);
        }
        if let Some(inner) = css_outer_parentheses(source) {
            return evaluate(inner, depth + 1);
        }
        supports_css_declaration(source)
    }

    evaluate(source, 0)
}

fn supports_css_declaration(source: &str) -> bool {
    let declarations = split_css_declarations(source);
    if declarations
        .iter()
        .filter(|(_, declaration)| !declaration.trim().is_empty())
        .count()
        != 1
    {
        return false;
    }
    let mut diagnostics = NativeDiagnosticSink::default();
    let _ = parse_declarations_with_diagnostics(
        source,
        NativeDiagnosticSource::Stylesheet { index: 0 },
        0,
        &mut diagnostics,
    );
    let (diagnostics, truncated) = diagnostics.finish();
    !truncated && diagnostics.is_empty()
}

fn css_outer_parentheses(source: &str) -> Option<&str> {
    let source = source.trim();
    if !source.starts_with('(') {
        return None;
    }
    let close = css_parenthesized_end(source.as_bytes(), 0)?;
    (close == source.len().saturating_sub(1)).then(|| source[1..close].trim())
}

fn css_split_top_level_keyword<'a>(source: &'a str, keyword: &str) -> Option<Vec<&'a str>> {
    let bytes = source.as_bytes();
    let keyword = keyword.as_bytes();
    let mut parts = Vec::new();
    let mut start = 0usize;
    let mut depth = 0usize;
    let mut quote = None;
    let mut escaped = false;
    let mut cursor = 0usize;
    while cursor < bytes.len() {
        if let Some(delimiter) = quote {
            if escaped {
                escaped = false;
            } else if bytes[cursor] == b'\\' {
                escaped = true;
            } else if bytes[cursor] == delimiter {
                quote = None;
            }
            cursor += 1;
            continue;
        }
        if bytes.get(cursor..cursor.saturating_add(2)) == Some(b"/*") {
            let end = bytes[cursor + 2..]
                .windows(2)
                .position(|window| window == b"*/")?;
            cursor = cursor + 2 + end + 2;
            continue;
        }
        match bytes[cursor] {
            b'\'' | b'"' => quote = Some(bytes[cursor]),
            b'(' => depth = depth.checked_add(1)?,
            b')' => depth = depth.checked_sub(1)?,
            _ => {}
        }
        if depth == 0
            && cursor + keyword.len() <= bytes.len()
            && bytes[cursor..cursor + keyword.len()].eq_ignore_ascii_case(keyword)
            && (cursor == 0 || bytes[cursor - 1].is_ascii_whitespace())
            && (cursor + keyword.len() == bytes.len()
                || bytes[cursor + keyword.len()].is_ascii_whitespace())
        {
            let part = source[start..cursor].trim();
            if part.is_empty() {
                return None;
            }
            parts.push(part);
            cursor += keyword.len();
            start = cursor;
            continue;
        }
        if bytes[cursor] == b'\\' {
            cursor = cursor.saturating_add(1);
        } else {
            cursor += 1;
        }
    }
    if quote.is_some() || depth != 0 {
        return None;
    }
    if parts.is_empty() {
        return None;
    }
    let part = source[start..].trim();
    (!part.is_empty()).then(|| {
        parts.push(part);
        parts
    })
}

fn css_top_level_segments(source: &str, separator: u8) -> Option<Vec<&str>> {
    let bytes = source.as_bytes();
    let mut segments = Vec::new();
    let mut start = 0usize;
    let mut depth = 0usize;
    let mut quote = None;
    let mut escaped = false;
    let mut cursor = 0usize;
    while cursor < bytes.len() {
        if let Some(delimiter) = quote {
            if escaped {
                escaped = false;
            } else if bytes[cursor] == b'\\' {
                escaped = true;
            } else if bytes[cursor] == delimiter {
                quote = None;
            }
            cursor += 1;
            continue;
        }
        if bytes.get(cursor..cursor.saturating_add(2)) == Some(b"/*") {
            let end = bytes[cursor + 2..]
                .windows(2)
                .position(|window| window == b"*/")?;
            cursor = cursor + 2 + end + 2;
            continue;
        }
        match bytes[cursor] {
            b'\'' | b'"' => quote = Some(bytes[cursor]),
            b'(' => depth = depth.checked_add(1)?,
            b')' => depth = depth.checked_sub(1)?,
            value if value == separator && depth == 0 => {
                let segment = source[start..cursor].trim();
                if segment.is_empty() {
                    return None;
                }
                segments.push(segment);
                start = cursor + 1;
            }
            _ => {}
        }
        if bytes[cursor] == b'\\' {
            cursor = cursor.saturating_add(1);
        } else {
            cursor += 1;
        }
    }
    if quote.is_some() || depth != 0 {
        return None;
    }
    let segment = source[start..].trim();
    if segment.is_empty() {
        return None;
    }
    segments.push(segment);
    Some(segments)
}

fn css_top_level_words(source: &str) -> Option<Vec<&str>> {
    let bytes = source.as_bytes();
    let mut words = Vec::new();
    let mut start = 0usize;
    let mut depth = 0usize;
    let mut quote = None;
    let mut escaped = false;
    let mut cursor = 0usize;
    while cursor < bytes.len() {
        if let Some(delimiter) = quote {
            if escaped {
                escaped = false;
            } else if bytes[cursor] == b'\\' {
                escaped = true;
            } else if bytes[cursor] == delimiter {
                quote = None;
            }
            cursor += 1;
            continue;
        }
        if bytes.get(cursor..cursor.saturating_add(2)) == Some(b"/*") {
            let end = bytes[cursor + 2..]
                .windows(2)
                .position(|window| window == b"*/")?;
            if depth == 0 && start < cursor {
                words.push(source[start..cursor].trim());
            }
            cursor = cursor + 2 + end + 2;
            start = cursor;
            continue;
        }
        match bytes[cursor] {
            b'\'' | b'"' => quote = Some(bytes[cursor]),
            b'(' => depth = depth.checked_add(1)?,
            b')' => depth = depth.checked_sub(1)?,
            byte if byte.is_ascii_whitespace() && depth == 0 => {
                if start < cursor {
                    words.push(source[start..cursor].trim());
                }
                cursor += 1;
                while cursor < bytes.len() && bytes[cursor].is_ascii_whitespace() {
                    cursor += 1;
                }
                start = cursor;
                continue;
            }
            _ => {}
        }
        if bytes[cursor] == b'\\' {
            cursor = cursor.saturating_add(1);
        } else {
            cursor += 1;
        }
    }
    if quote.is_some() || depth != 0 {
        return None;
    }
    if start < bytes.len() {
        words.push(source[start..].trim());
    }
    words.retain(|word| !word.is_empty());
    Some(words)
}

fn stylesheet_base_url(document_url: &str, stylesheet_href: &str) -> Option<Url> {
    let document_url = Url::parse(document_url).ok()?;
    let document_is_file = document_url.scheme().eq_ignore_ascii_case("file");
    let document_is_network = matches!(
        document_url.scheme().to_ascii_lowercase().as_str(),
        "http" | "https"
    );
    if !document_is_file && !document_is_network {
        return None;
    }
    if !document_url.username().is_empty() || document_url.password().is_some() {
        return None;
    }
    let mut stylesheet_url = document_url.join(stylesheet_href).ok()?;
    let stylesheet_is_file = stylesheet_url.scheme().eq_ignore_ascii_case("file");
    let stylesheet_is_network = matches!(
        stylesheet_url.scheme().to_ascii_lowercase().as_str(),
        "http" | "https"
    );
    if !stylesheet_is_file && !stylesheet_is_network {
        return None;
    }
    if document_is_file != stylesheet_is_file
        || document_is_network != stylesheet_is_network
        || !stylesheet_url.username().is_empty()
        || stylesheet_url.password().is_some()
    {
        return None;
    }
    stylesheet_url.set_fragment(None);
    Some(stylesheet_url)
}

fn css_url_function_open(bytes: &[u8], cursor: usize) -> Option<usize> {
    css_named_function_open(bytes, cursor, b"url")
}

fn css_named_function_open(bytes: &[u8], cursor: usize, name: &[u8]) -> Option<usize> {
    let end = cursor.checked_add(name.len())?;
    if end > bytes.len()
        || !bytes[cursor..end].eq_ignore_ascii_case(name)
        || (cursor > 0 && is_css_identifier_byte(bytes[cursor - 1]))
        || (end < bytes.len() && is_css_identifier_byte(bytes[end]))
    {
        return None;
    }
    let mut open = end;
    while open < bytes.len() && bytes[open].is_ascii_whitespace() {
        open += 1;
    }
    (bytes.get(open) == Some(&b'(')).then_some(open)
}

fn css_url_function_close(bytes: &[u8], start: usize) -> Option<usize> {
    let mut quote = None;
    let mut escaped = false;
    let mut offset = start;
    while offset < bytes.len() {
        let byte = bytes[offset];
        if let Some(expected) = quote {
            if escaped {
                escaped = false;
            } else if byte == b'\\' {
                escaped = true;
            } else if byte == expected {
                quote = None;
            }
            offset += 1;
            continue;
        }
        match byte {
            b'\'' | b'"' => quote = Some(byte),
            b')' => return Some(offset),
            b'\\' => {
                offset = offset.saturating_add(2);
                continue;
            }
            _ => {}
        }
        offset += 1;
    }
    None
}

fn is_css_identifier_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-')
}

/// Decode CSS escape sequences inside a URL token before handing the value to
/// the URL parser. This is intentionally scoped to URL-like tokens: selector,
/// declaration, and string parsing retain their existing owners. Invalid
/// trailing escapes are rejected so a file capability cannot resolve a
/// partially interpreted path.
pub(crate) fn decode_css_url_value(value: &str) -> Option<String> {
    let mut decoded = String::with_capacity(value.len());
    let mut chars = value.chars().peekable();
    while let Some(character) = chars.next() {
        if character != '\\' {
            decoded.push(character);
            continue;
        }
        let Some(next) = chars.next() else {
            return None;
        };
        if next == '\n' {
            continue;
        }
        if next == '\r' {
            if chars.peek() == Some(&'\n') {
                chars.next();
            }
            continue;
        }
        if next.is_ascii_hexdigit() {
            let mut digits = String::with_capacity(6);
            digits.push(next);
            while digits.len() < 6
                && chars
                    .peek()
                    .is_some_and(|candidate| candidate.is_ascii_hexdigit())
            {
                digits.push(chars.next().expect("peeked CSS hex escape"));
            }
            if chars.peek().is_some_and(char::is_ascii_whitespace) {
                chars.next();
            }
            let codepoint = u32::from_str_radix(&digits, 16).ok()?;
            decoded.push(
                (codepoint != 0)
                    .then(|| char::from_u32(codepoint))
                    .flatten()
                    .unwrap_or('\u{fffd}'),
            );
        } else {
            decoded.push(next);
        }
    }
    Some(decoded)
}

fn resolve_css_url_token(token: &str, base_url: &Url) -> Option<String> {
    let (quoted, value) = if token.len() >= 2
        && matches!(token.as_bytes().first(), Some(b'\'' | b'"'))
        && token.as_bytes().last() == token.as_bytes().first()
    {
        (
            Some(token.as_bytes()[0] as char),
            &token[1..token.len() - 1],
        )
    } else {
        (None, token)
    };
    let value = decode_css_url_value(value)?;
    if value.is_empty() || value.starts_with('#') || value.bytes().any(|byte| byte == 0) {
        return None;
    }
    let target = Url::parse(&value).or_else(|_| base_url.join(&value)).ok()?;
    let base_is_file = base_url.scheme().eq_ignore_ascii_case("file");
    let target_is_file = target.scheme().eq_ignore_ascii_case("file");
    let target_is_network = matches!(
        target.scheme().to_ascii_lowercase().as_str(),
        "http" | "https"
    );
    if (base_is_file != target_is_file)
        || (!base_is_file && !target_is_network)
        || !target.username().is_empty()
        || target.password().is_some()
    {
        return None;
    }
    let target = target.to_string();
    quoted.map_or_else(
        || Some(target.clone()),
        |quote| Some(format!("{quote}{target}{quote}")),
    )
}

fn register_background_image_source(
    source: &str,
    background_image_sources: &mut BTreeMap<u32, String>,
) {
    let source_id = background_image_source_id(source);
    if background_image_sources
        .get(&source_id)
        .is_none_or(|existing| existing == source)
    {
        background_image_sources
            .entry(source_id)
            .or_insert_with(|| source.to_owned());
    }
}

fn split_css_value_tokens(value: &str) -> Option<Vec<&str>> {
    let mut tokens = Vec::new();
    let mut start = None;
    let mut parentheses = 0usize;
    for (index, byte) in value.bytes().enumerate() {
        match byte {
            b'(' => {
                if start.is_none() {
                    start = Some(index);
                }
                parentheses = parentheses.checked_add(1)?;
            }
            b')' => {
                parentheses = parentheses.checked_sub(1)?;
            }
            byte if byte.is_ascii_whitespace() && parentheses == 0 => {
                if let Some(start) = start.take() {
                    tokens.push(&value[start..index]);
                }
            }
            _ if start.is_none() => start = Some(index),
            _ => {}
        }
    }
    if parentheses != 0 {
        return None;
    }
    if let Some(start) = start {
        tokens.push(&value[start..]);
    }
    (!tokens.is_empty()).then_some(tokens)
}

fn parse_border_radius(value: &str) -> Option<NativeBorderRadius> {
    if value.contains('/') {
        return None;
    }
    let values = value
        .split_ascii_whitespace()
        .map(parse_dimension)
        .collect::<Option<Vec<_>>>()?;
    match values.as_slice() {
        [all] => Some(NativeBorderRadius {
            top_left: *all,
            top_right: *all,
            bottom_right: *all,
            bottom_left: *all,
        }),
        [top_left, top_right] => Some(NativeBorderRadius {
            top_left: *top_left,
            top_right: *top_right,
            bottom_right: *top_left,
            bottom_left: *top_right,
        }),
        [top_left, top_right, bottom_right] => Some(NativeBorderRadius {
            top_left: *top_left,
            top_right: *top_right,
            bottom_right: *bottom_right,
            bottom_left: *top_right,
        }),
        [top_left, top_right, bottom_right, bottom_left] => Some(NativeBorderRadius {
            top_left: *top_left,
            top_right: *top_right,
            bottom_right: *bottom_right,
            bottom_left: *bottom_left,
        }),
        _ => None,
    }
}

fn parse_border_radius_declaration(
    value: &str,
) -> Option<LocalCascadeDeclaration<NativeBorderRadiusValue>> {
    let value = value.trim();
    if value.eq_ignore_ascii_case("revert-layer") {
        return Some(LocalCascadeDeclaration::RevertLayer);
    }
    let css_wide = if value.eq_ignore_ascii_case("inherit") {
        Some(NativeBorderRadiusValue::Inherit)
    } else if value.eq_ignore_ascii_case("unset") {
        Some(NativeBorderRadiusValue::Unset)
    } else if value.eq_ignore_ascii_case("initial") {
        Some(NativeBorderRadiusValue::Initial)
    } else if value.eq_ignore_ascii_case("revert") {
        Some(NativeBorderRadiusValue::Revert)
    } else {
        None
    };
    css_wide
        .or_else(|| parse_border_radius(value).map(NativeBorderRadiusValue::Radius))
        .map(LocalCascadeDeclaration::Value)
}

